import type { LumaEvent } from "../../constants/luma-events";

// Newest first, id as a tiebreak, so the generated file reads like the
// archive and scrape runs produce minimal, reviewable diffs.
export function sortByStart(events: Record<string, LumaEvent>): Record<string, LumaEvent> {
  const keys = Object.keys(events).sort((a, b) => {
    const byStart = new Date(events[b].start_at).getTime() - new Date(events[a].start_at).getTime();
    return byStart !== 0 ? byStart : a.localeCompare(b);
  });
  return Object.fromEntries(keys.map((key) => [key, events[key]]));
}

// JSON.stringify output is also a valid TypeScript object literal, so no AST
// library is needed. Titles with quotes or emoji are JSON-escaped.
export function renderGeneratedFile(events: Record<string, LumaEvent>): string {
  const literal = JSON.stringify(sortByStart(events), null, 2);
  return `import type { LumaEvent } from "./luma-events";

// AUTO-GENERATED by \`pnpm scrape:luma\`. Do not edit by hand.
// Human curation lives in events.ts, which wins over entries here.
export const generatedLumaEvents = ${literal} satisfies Record<string, LumaEvent>;
`;
}
